  `Photo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `IsWorking` tinyint(1) DEFAULT NULL,
  `RoleNames` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`EmployeeID`),
