CREATE TABLE `orders` (
  `OrderID` int NOT NULL AUTO_INCREMENT,
  `CustomerID` int DEFAULT NULL,
  `OrderTime` datetime NOT NULL,
  `DeliveryProvince` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `DeliveryAddress` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `EmployeeID` int DEFAULT NULL,
  `AcceptTime` datetime DEFAULT NULL,
  `ShipperID` int DEFAULT NULL,
  `ShippedTime` datetime DEFAULT NULL,
  `FinishedTime` datetime DEFAULT NULL,
  `Status` int NOT NULL,
  PRIMARY KEY (`OrderID`),
  KEY `FK_Orders_Customers` (`CustomerID`),
  KEY `FK_Orders_Employees` (`EmployeeID`),
  KEY `FK_Orders_OrderStatus` (`Status`),
  KEY `FK_Orders_Shippers` (`ShipperID`),
  CONSTRAINT `FK_Orders_Customers` FOREIGN KEY (`CustomerID`) REFERENCES `customers` (`CustomerID`),
  CONSTRAINT `FK_Orders_Employees` FOREIGN KEY (`EmployeeID`) REFERENCES `employees` (`EmployeeID`),
  CONSTRAINT `FK_Orders_OrderStatus` FOREIGN KEY (`Status`) REFERENCES `orderstatus` (`Status`),
  CONSTRAINT `FK_Orders_Shippers` FOREIGN KEY (`ShipperID`) REFERENCES `shippers` (`ShipperID`)
) ENGINE=InnoDB AUTO_INCREMENT=1021 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
